describe('Dark Mode Toggle Feature', () => {
  beforeEach(() => {
    cy.visit('/preferences');
    cy.get('[data-testid="preferences-page"]').should('be.visible');
  });

  it('should toggle dark mode on and display dark theme', () => {
    // Verify initial state is light mode
    cy.get('body').should('have.class', 'light-mode');
    cy.get('[data-testid="dark-mode-toggle"]').should('not.be.checked');

    // Toggle dark mode on
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Verify dark mode is enabled
    cy.get('[data-testid="dark-mode-toggle"]').should('be.checked');
    cy.get('body').should('have.class', 'dark-mode');
    cy.get('body').should('not.have.class', 'light-mode');

    // Verify dark mode styles are applied
    cy.get('[data-testid="preferences-container"]').should(
      'have.css',
      'background-color',
      'rgb(33, 33, 33)'
    );

    // Verify preference is persisted
    cy.get('[data-testid="save-preferences-btn"]').click();
    cy.get('[data-testid="success-message"]').should('contain', 'Preferences saved');
  });

  it('should toggle dark mode off and return to light theme', () => {
    // Enable dark mode first
    cy.get('[data-testid="dark-mode-toggle"]').click();
    cy.get('body').should('have.class', 'dark-mode');

    // Toggle dark mode off
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Verify light mode is restored
    cy.get('[data-testid="dark-mode-toggle"]').should('not.be.checked');
    cy.get('body').should('have.class', 'light-mode');
    cy.get('body').should('not.have.class', 'dark-mode');

    // Verify light mode styles are applied
    cy.get('[data-testid="preferences-container"]').should(
      'have.css',
      'background-color',
      'rgb(255, 255, 255)'
    );
  });

  it('should persist dark mode preference across page reload', () => {
    // Enable dark mode
    cy.get('[data-testid="dark-mode-toggle"]').click();
    cy.get('[data-testid="save-preferences-btn"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Reload page
    cy.reload();

    // Verify dark mode is still enabled
    cy.get('[data-testid="dark-mode-toggle"]').should('be.checked');
    cy.get('body').should('have.class', 'dark-mode');
  });

  it('should handle rapid toggle clicks without errors', () => {
    // Perform rapid clicks
    cy.get('[data-testid="dark-mode-toggle"]').click();
    cy.get('[data-testid="dark-mode-toggle"]').click();
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Verify final state is dark mode (odd number of clicks)
    cy.get('[data-testid="dark-mode-toggle"]').should('be.checked');
    cy.get('body').should('have.class', 'dark-mode');

    // Verify no error messages appear
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should update all UI elements when dark mode is toggled', () => {
    // Toggle dark mode on
    cy.get('[data-testid="dark-mode-toggle"]').click();

    // Verify header styling
    cy.get('[data-testid="header"]').should('have.class', 'dark-mode-header');

    // Verify sidebar styling
    cy.get('[data-testid="sidebar"]').should('have.class', 'dark-mode-sidebar');

    // Verify text color contrast
    cy.get('[data-testid="preferences-title"]').should(
      'have.css',
      'color',
      'rgb(255, 255, 255)'
    );

    // Verify button styling
    cy.get('[data-testid="save-preferences-btn"]').should(
      'have.class',
      'dark-mode-button'
    );
  });
});
